python3 -c "import json,urllib.request,urllib.error; token='b8d6f01528fe515ead5390d3c408ea79b2b34c3f39eefebc004efdc02734284b'; payload=json.dumps({'action':'render_trigger_deploy','input':{},'confirm':True,'confirmText':'CONFIRM_IVX_RENDER_DEPLOY','reason':'Owner-authorized deploy of current GitHub main edf62a9f4940fb85d9b1b49406608b955861094d; verify SHA parity after Render reaches Live.'}).encode(); request=urllib.request.Request('https://api.ivxholding.com/api/ivx/developer-deploy/action',data=payload,method='POST',headers={'Content-Type':'application/json','Accept':'application/json','Authorization':'Bearer '+token});
try:
 with urllib.request.urlopen(request,timeout=45) as response:
  body=json.load(response); result=body.get('result',{}); print(json.dumps({'httpStatus':response.status,'ok':body.get('ok'),'action':body.get('action'),'provider':result.get('provider'),'deployId':result.get('deployId') or result.get('id'),'status':result.get('status'),'message':result.get('message'),'secretValuesReturned':body.get('secretValuesReturned')},sort_keys=True))
except urllib.error.HTTPError as error:
 raw=error.read().decode('utf-8');
 try: body=json.loads(raw)
 except Exception: body={'error':'Non-JSON error response'}
 print(json.dumps({'httpStatus':error.code,'ok':body.get('ok'),'error':body.get('error'),'message':body.get('message'),'confirmTextRequired':body.get('confirmTextRequired'),'secretValuesReturned':body.get('secretValuesReturned')},sort_keys=True))"

